    /// <summary>
    /// Blank record must not be inserted into the table
    /// </summary>
    /// <returns>True, if validations are clear, else False</returns>
    public boolean validateWrite()
    {
        boolean ret;
    
        ret = super();

        if(!(this.CustAccount || this.VendAccount))
        {
            ret = false;
        }
    
        return ret;
    }

    /// <summary>
    ///
    /// </summary>
    static METRebateScanSupplierTable find(METRebateTransId _rebateTransId, boolean _forUpdate = false)
    {
        METRebateScanSupplierTable externalSellData;

        if (_rebateTransId)
        {
            if (_forUpdate)
            {
                externalSellData.selectForUpdate(_forUpdate);
            }

            select firstonly externalSellData
                where externalSellData.TransactionNumber == _rebateTransId;
        }

        return externalSellData;
    }

    /// <summary>
    /// Bug 284448: CB705 - Vendor Claims external data source does not link the transaction to METExternalSellData table
    /// </summary>
    static METRebateScanSupplierTable findRecId(RecId   _recId, 
                                                boolean _forUpdate = false)
    {
        METRebateScanSupplierTable externalSellData;

        if (_recId)
        {
            externalSellData.selectForUpdate(_forUpdate);

            select firstonly externalSellData
                where externalSellData.RecId == _recId;
        }

        return externalSellData;
    }

    /// <summary>
    /// Bug 284448: CB705 - Vendor Claims external data source does not link the transaction to METExternalSellData table
    /// Method to update the processed flags based on the scenario
    /// </summary>
    /// <param name = "_rebateTransactionType">Rebate transaction type</param>
    /// <param name = "_value">Flag value</param>
    /// <param name = "_rebateTransId"><c>TAMRebateTransId</c></param>
    static void updateProcessedFlags(TAMRebateTransactionType _rebateTransactionType, System.Object _value, TAMRebateTransId _rebateTransId, RefRecId _externalSellDataRecId = 0)
    {
        METRebateScanSupplierTable externalSellData;
        TAMRebateTrans  rebateTrans; 
        FieldName settingField;

        if (_rebateTransactionType == TAMRebateTransactionType::Provision)
        {
            settingField = fieldStr(METRebateScanSupplierTable, ProvisionProcessed);
        }
        else if (_rebateTransactionType == TAMRebateTransactionType::Rebate)
        {
            settingField = fieldStr(METRebateScanSupplierTable, RebateProcessed);
        }

        if (settingField)
        {
            var rebateTransQo = new SysDaQueryObject(rebateTrans);
            var uo = new SysDaUpdateObject(externalSellData);
            
            uo.settingClause().add(settingField, new SysDaValueExpression(_value));

            rebateTransQo.whereClause(new SysDaEqualsExpression(
                new SysDaFieldExpression(rebateTrans, fieldStr(TAMRebateTrans, RefCompanyId)),
                new SysDaFieldExpression(externalSellData, fieldStr(METRebateScanSupplierTable, DataAreaId)))
            .and(new SysDaEqualsExpression(
                new SysDaFieldExpression(rebateTrans, fieldStr(TAMRebateTrans, RefRecId)),
                new SysDaFieldExpression(externalSellData, fieldStr(METRebateScanSupplierTable, RecId))))
            .and(new SysDaEqualsExpression(
                new SysDaFieldExpression(rebateTrans, fieldStr(TAMRebateTrans, RefTableId)),
                new SysDaValueExpression(tableNum(METRebateScanSupplierTable))))
            .and(new SysDaEqualsExpression(
                new SysDaFieldExpression(rebateTrans, fieldStr(TAMRebateTrans, RebateTransId)),
                new SysDaValueExpression(_rebateTransId))));

            uo.joinClause(SysDaJoinKind::ExistsJoin, rebateTransQo);

            if (_externalSellDataRecId)
            {
                uo.whereClause(new SysDaEqualsExpression(
                    new SysDaFieldExpression(externalSellData, settingField),
                    new SysDaValueExpression(!_value))
                .and(new SysDaEqualsExpression(
                    new SysDaFieldExpression(externalSellData, fieldStr(METRebateScanSupplierTable, RecId)),
                    new SysDaValueExpression(_externalSellDataRecId))));
            }
            else
            {
                uo.whereClause(new SysDaEqualsExpression(
                    new SysDaFieldExpression(externalSellData, settingField),
                    new SysDaValueExpression(!_value)));
            }

            /*update_recordset externalSellData
            setting ProvisionProcessed = NoYes::Yes
            exists join rebateTrans
            where rebateTrans.RefCompanyId == externalSellData.DataAreaId
            && rebateTrans.RefTableId == tableNum(METRebateScanSupplierTable)
            && rebateTrans.RefRecId == externalSellData.RecId
            && rebateTrans.RebateTransId == _rebateTransId
            && externalSellData.ProvisionProcessed == NoYes::No;*/

            ttsbegin;
            new SysDaUpdateStatement().update(uo);
            ttscommit;
        }

    }
